import React from "react";
import { useCart } from "../components/CartContext";

const Cart = () => {
  const { cartItems } = useCart();

  return (
    <div style={{
      padding: "40px",
      backgroundColor: "#f9f9f9",
      minHeight: "100vh",
      fontFamily: "Arial, sans-serif",
    }}>
      <h2 style={{
        fontSize: "28px",
        fontWeight: "bold",
        marginBottom: "30px",
        color: "#333",
        textAlign: "center"
      }}>
        🛒 Your Cart
      </h2>

      {cartItems.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666", fontSize: "18px" }}>
          No items in the cart.
        </p>
      ) : (
        <div style={{
          maxWidth: "600px",
          margin: "0 auto",
          backgroundColor: "#fff",
          borderRadius: "12px",
          boxShadow: "0 4px 16px rgba(0,0,0,0.1)",
          padding: "25px"
        }}>
          <ul style={{ listStyle: "none", padding: 0 }}>
            {cartItems.map((item, index) => (
              <li key={index} style={{
                borderBottom: "1px solid #e0e0e0",
                padding: "15px 0",
                fontSize: "18px",
                display: "flex",
                justifyContent: "space-between"
              }}>
                <span>{item.name}</span>
                <span style={{ fontWeight: 600 }}>₹{item.price}</span>
              </li>
            ))}
          </ul>
          <div style={{
            textAlign: "right",
            fontSize: "20px",
            fontWeight: "bold",
            marginTop: "20px",
            color: "#28a745"
          }}>
            Total: ₹{cartItems.reduce((sum, item) => sum + Number(item.price), 0)}
          </div>
        </div>
      )}
    </div>
  );
};

export default Cart;
